-- Generated from the existing curated frontend catalog. No new hotel facts are invented here.
on conflict (id) do update set recognition_score=excluded.recognition_score,cost_profile=excluded.cost_profile,cost_source=excluded.cost_source,cost_confidence=excluded.cost_confidence,cost_last_updated=excluded.cost_last_updated,updated_at=now();

on conflict (destination_id,normalized_name,provider) do update set booking_com_property_url=excluded.booking_com_property_url,cj_tracking_url=excluded.cj_tracking_url,provider_property_id=excluded.provider_property_id,style_tags=excluded.style_tags,updated_at=now();
